"""Brute-force solvers for the two problems, used only for testing."""
from __future__ import annotations

import itertools


def solve_three_sat(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        # variable v (1..m) -> bits[v-1]
        ok = True
        for clause in clauses:
            if not any((bits[abs(l) - 1] if l > 0 else not bits[abs(l) - 1]) for l in clause):
                ok = False
                break
        if ok:
            return True
    return False


def solve_independent_set(instance):
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    edge_set = set()
    for u, v in edges:
        edge_set.add((u, v))
        edge_set.add((v, u))
    for r in range(k, n + 1):
        for subset in itertools.combinations(range(n), r):
            s = set(subset)
            good = True
            for u, v in edges:
                if u in s and v in s:
                    good = False
                    break
            if good:
                return True
    return False
